script:
/* Cheque inventory only; payment approvals remain on the payment documents. */
frappe.ui.form.on('Cheque Book', {
    setup: function(frm) {
        frm.set_query('account', function() {
            return {filters: {account_type: 'Bank', is_group: 0}};
        });
    },
    refresh: function(frm) {
        if (frm._cheque_inventory_section) {
            frm._cheque_inventory_section.remove();
            frm._cheque_inventory_section = null;
        }
        if (frm.is_new()) {
            ['account', 'first_leaf_no', 'last_leaf_no', 'book_name'].forEach(function(field) {
                frm.set_df_property(field, 'read_only', 0);
            });
            return;
        }
        const book_name = frm.doc.name;
        frm.add_custom_button(__('View Cheque Leaves'), function() {
            frappe.set_route('List', 'Cheque Leaf', {cheque_book: book_name});
        });
        if (frm.doc.status === 'Active' && frm.perm[0] && frm.perm[0].write) {
            frm.add_custom_button(__('Generate Missing Leaves'), function() {
                if (frm.is_dirty()) {
                    frappe.msgprint(__('Save the cheque book before generating leaves.'));
                    return;
                }
                frappe.confirm(
                    __('This will create the remaining cheque leaves in this book’s saved number range. Existing leaves will stay unchanged. Created leaves cannot be deleted; unused leaves can be cancelled. Continue?'),
                    function() {
                        frappe.call({
                            method: 'worldshading.api.cheque_register.generate_leaves',
                            args: {book_name: book_name},
                            freeze: true,
                            freeze_message: __('Generating cheque leaves...'),
                            callback: function(r) {
                                if (r.exc || !r.message) return;
                                frappe.msgprint(__('Created {0} cheque leaves. {1} already existed.',
                                    [r.message.created, r.message.existing]));
                                frm.reload_doc();
                            }
                        });
                    }
                );
            });
        }
        frappe.call({
            method: 'worldshading.api.cheque_register.get_book_summary',
            args: {book_name: book_name},
            callback: function(r) {
                if (r.exc || !r.message || frm.doc.name !== book_name) return;
                if (frm._cheque_inventory_section) frm._cheque_inventory_section.remove();
                const summary = r.message;
                const cards = [
                    {label: __('Created Leaves'), count: summary.total},
                    {label: __('Book Capacity'), count: summary.expected, capacity: true}
                ];
                ['Available', 'Reserved', 'Issued', 'Cleared', 'Cancelled', 'Bounced'].forEach(function(status) {
                    cards.push({label: __(status), count: summary.counts[status] || 0, status: status});
                });
                const html = '<div class="row">' + cards.map(function(card, index) {
                    return '<div class="col-xs-6 col-sm-3" style="margin-bottom:12px">' +
                        '<button class="btn btn-default btn-block" data-cheque-card="' + index + '">' +
                        '<strong>' + cint(card.count) + '</strong><br>' +
                        frappe.utils.escape_html(card.label) + '</button></div>';
                }).join('') + '</div>';
                frm.dashboard.show();
                frm._cheque_inventory_section = frm.dashboard.add_section(html);
                frm._cheque_inventory_section.find('[data-cheque-card]').on('click', function() {
                    const card = cards[Number($(this).attr('data-cheque-card'))];
                    if (card.capacity) {
                        frappe.msgprint(__('Book capacity is {0} leaves. Use Generate Missing Leaves to complete its inventory.',
                            [summary.expected]));
                        return;
                    }
                    const filters = {cheque_book: book_name};
                    if (card.status) filters.status = card.status;
                    frappe.set_route('List', 'Cheque Leaf', filters);
                });
                ['account', 'first_leaf_no', 'last_leaf_no', 'book_name'].forEach(function(field) {
                    frm.set_df_property(field, 'read_only', summary.total > 0 ? 1 : 0);
                });
            }
        });
    }
});

frappe.ui.form.on('Cheque Leaf', {
    refresh: function(frm) {
        frm.set_df_property('damaged', 'read_only', 1);
        frm.set_df_property('cheque_attachment', 'read_only', 1);
        if (frm.doc.cheque_book) {
            frm.add_custom_button(__('Open Cheque Book'), function() {
                frappe.set_route('Form', 'Cheque Book', frm.doc.cheque_book);
            });
        }
        ['cheque_book', 'cheque_number'].forEach(function(field) {
            frm.set_df_property(field, 'read_only', frm.is_new() ? 0 : 1);
        });
        if (frm.is_new()) return;
        if (frm._payment_attachment_section) frm._payment_attachment_section.remove();
        const request = {};
        frm._payment_attachment_request = request;
        const owner = frm.doc.payment_entry || frm.doc.gl_payment || frm.doc.journal_entry;
        if (owner) {
            const section = frm.dashboard.add_section('<h6>' + __('Payment Attachments') + '</h6><p class="text-muted">' + __('Loading...') + '</p>');
            frm._payment_attachment_section = section;
            frm.dashboard.show();
            frappe.call({
                method: 'worldshading.api.cheque_payments.get_leaf_attachments',
                args: {leaf_name: frm.doc.name},
                callback: function(r) {
                    if (frm._payment_attachment_request !== request) return;
                    const data = r.message || {};
                    const escape = frappe.utils.escape_html;
                    const files = (data.files || []).filter(function(file) {
                        return /^(\/files\/|\/private\/files\/|https?:\/\/)/.test(file.file_url || '');
                    });
                    let html = '<h6>' + __('Payment Attachments') + '</h6>';
                    if (data.payment_name) html += '<p class="text-muted">' + escape(data.payment_type + ': ' + data.payment_name) + '</p>';
                    if (data.restricted) html += '<p class="text-muted">' + __('You do not have permission to view this payment’s attachments.') + '</p>';
                    else if (!files.length) html += '<p class="text-muted">' + __('No payment attachments yet.') + '</p>';
                    else html += '<ul>' + files.map(function(file) {
                        return '<li><a target="_blank" rel="noopener noreferrer" href="' + escape(file.file_url).replace(/"/g, '&quot;').replace(/'/g, '&#39;') + '">' +
                            escape(file.file_name || file.file_url) + '</a></li>';
                    }).join('') + '</ul>';
                    section.html(html);
                },
                error: function() {
                    if (frm._payment_attachment_request === request) section.html('<p class="text-muted">' + __('Unable to load payment attachments.') + '</p>');
                }
            });
        }
        const linked = frm.doc.payment_entry || frm.doc.gl_payment || frm.doc.journal_entry;
        if (frm.doc.status !== 'Available' || frm.doc.signed || linked || !frm.perm[0] || !frm.perm[0].write) return;
        frm.add_custom_button(__('Cancel Unused Leaf'), function() {
            if (frm.is_dirty()) {
                frappe.msgprint(__('Save the cheque leaf before cancelling it.'));
                return;
            }
            let damage_file = null, completed = false, saving = false, dialog;
            dialog = new frappe.ui.Dialog({
                title: __('Cancel Unused Cheque Leaf'),
                fields: [
                    {fieldname: 'damaged', label: __('Damaged'), fieldtype: 'Check', default: 0,
                        onchange: function() {
                            if (dialog) dialog.fields_dict.damage_upload.$wrapper.toggle(!!dialog.get_value('damaged'));
                        }},
                    {fieldname: 'reason', label: __('Reason'), fieldtype: 'Small Text', reqd: 1},
                    {fieldname: 'damage_upload', fieldtype: 'HTML',
                        options: '<p>' + __('A photo or document is required when Damaged is selected. It will be saved privately on this leaf.') + '</p><div class="damage-upload-area"></div>'}
                ],
                primary_action_label: __('Cancel Leaf'),
                primary_action: function(values) {
                    if (completed || saving) return;
                    if (frm.is_dirty()) { frappe.msgprint(__('Save the changed cheque leaf before cancelling.')); return; }
                    const reason = String(values.reason || '').trim();
                    if (!reason) { frappe.msgprint(__('Enter a cancellation reason.')); return; }
                    if (values.damaged && !damage_file) {
                        frappe.msgprint(__('Upload the damaged cheque photo or document before continuing.'));
                        return;
                    }
                    saving = true;
                    frappe.call({
                        method: 'worldshading.api.cheque_register.cancel_unused_leaf',
                        args: {leaf_name: frm.doc.name, reason: reason, damaged: values.damaged || 0, damage_file: values.damaged ? damage_file : null},
                        freeze: true,
                        callback: function(r) {
                            saving = false;
                            if (r.exc || r.message !== frm.doc.name) return;
                            completed = true;
                            dialog.hide();
                            frm.reload_doc();
                        },
                        error: function() { saving = false; }
                    });
                }
            });
            // Toggle the preserved wrapper, without refreshing/destroying Vue.
            dialog.fields_dict.damage_upload.$wrapper.toggle(!!dialog.get_value('damaged'));
            dialog.onhide = function() { completed = true; };
            dialog.show();
            new frappe.ui.FileUploader({
                doctype: 'Cheque Leaf', docname: frm.doc.name,
                wrapper: dialog.fields_dict.damage_upload.$wrapper.find('.damage-upload-area'), disable_file_browser: true,
                method: 'worldshading.api.cheque_register.upload_damaged_leaf_attachment',
                on_success: function(file) { if (!completed && file && file.name) damage_file = file.name; }
            });
        });
    }
});
